$body = $page->execute()->value();
if ($page->path() === '/' && isset($infosystems)) {
    // Only fixed, site-owned Infosystem views can fill these authored slots.
    // The Document contains no executable PHP and cannot select a handler.
    $slots = [
        'symptoms' => ['mechaniki_symptoms', 'mechaniki.home.problems', 100],
        'services' => ['mechaniki_services', 'mechaniki.home.services', 100],
        'prices' => ['mechaniki_prices', 'mechaniki.home.prices', 100],
        'works' => ['mechaniki_cases', 'mechaniki.home.cases', 10],
        'reviews' => ['mechaniki_reviews', 'mechaniki.home.reviews', 10],
        'faq' => ['mechaniki_faq', 'mechaniki.faq', 10],
    ];
    foreach ($slots as $slot => [$code, $view, $limit]) {
        $placeholder = '<div id="uv-slot-' . $slot . '"></div>';
        if (!str_contains($body, $placeholder)) {
            continue;
        }
        $html = $infosystems->get($code)->items()->limit($limit)->template($view)->show();
        $body = str_replace($placeholder, $html, $body);
    }
}
if (class_exists(\UltimaVox\Modules\Mechaniki\SiteMedia::class)) {
    $body = \UltimaVox\Modules\Mechaniki\SiteMedia::localizeHtml($body, dirname(__DIR__, 2));
}
echo \Core\View\SafeHtml::fromTrustedStorage($body);
?></main>
